schema_ddl:
CREATE TYPE stato_conto AS ENUM ('ATTIVO', 'SOSPESO', 'CHIUSO');

CREATE TYPE stato_prestito AS ENUM ('RICHIESTO', 'APPROVATO', 'EROGATO', 'ESTINTO', 'MOROSO');

CREATE TYPE tipo_transazione AS ENUM ('VERSAMENTO', 'PRELIEVO', 'BONIFICO_USCITA', 'BONIFICO_INGRESSO', 'COMMISSIONE');

CREATE TYPE stato_rata AS ENUM ('IN_ATTESA', 'PAGATA', 'INSOLUTA');

CREATE TABLE clienti (
    id BIGSERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    email TEXT UNIQUE
);

CREATE TABLE conti_correnti (
    id BIGSERIAL PRIMARY KEY,
    cliente_id BIGINT NOT NULL REFERENCES clienti(id),
    iban TEXT NOT NULL UNIQUE,
    saldo NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (saldo >= 0),
    stato_conto stato_conto NOT NULL DEFAULT 'ATTIVO',
    data_apertura DATE NOT NULL
);

CREATE TABLE prestiti (
    id BIGSERIAL PRIMARY KEY,
    cliente_id BIGINT NOT NULL REFERENCES clienti(id),
    capitale_erogato NUMERIC(14,2) NOT NULL CHECK (capitale_erogato > 0),
    tasso_interesse NUMERIC(5,2) NOT NULL CHECK (tasso_interesse BETWEEN 0 AND 100),
    durata_mesi INT NOT NULL CHECK (durata_mesi > 0),
    stato_prestito stato_prestito NOT NULL DEFAULT 'RICHIESTO',
    data_erogazione DATE
);

CREATE TABLE transazioni (
    id BIGSERIAL PRIMARY KEY,
    conto_id BIGINT NOT NULL REFERENCES conti_correnti(id),
    tipo_transazione tipo_transazione NOT NULL,
    importo NUMERIC(12,2) NOT NULL CHECK (importo <> 0),
    data_transazione TIMESTAMP NOT NULL,
    descrizione TEXT
);

CREATE TABLE rate_prestito (
    id BIGSERIAL PRIMARY KEY,
    prestito_id BIGINT NOT NULL REFERENCES prestiti(id),
    numero_rata INT NOT NULL CHECK (numero_rata > 0),
    importo_rata NUMERIC(12,2) NOT NULL CHECK (importo_rata > 0),
    data_scadenza DATE NOT NULL,
    stato_rata stato_rata NOT NULL DEFAULT 'IN_ATTESA',
    UNIQUE (prestito_id, numero_rata)
);
